using Microsoft.EntityFrameworkCore;
class AppDbContext : DbContext
{
    public DbSet<Order> Orders => Set<Order>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // EF Core 9 breaking change: HasData() now requires fixed seed data.
        // DateTime.UtcNow is non-deterministic and will cause migration issues.
        modelBuilder.Entity<Order>().HasData(
            new Order { Id = 1, CreatedAt = new DateTime(2024, 1, 1, 0, 0, 0, DateTimeKind.Utc) });
    }
}
class Order { public int Id { get; set; } public DateTime CreatedAt { get; set; } }

// --- Cosmos DB context demonstrating EF Core 9 breaking changes ---

class CosmosDbContext : DbContext
{
    public DbSet<Product> Products => Set<Product>();

    protected override void OnConfiguring(DbContextOptionsBuilder optionsBuilder)
    {
        optionsBuilder.UseCosmos(
            "AccountEndpoint=https://localhost:8081/;AccountKey=placeholder",
            "CatalogDb");
    }

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Product>(b =>
        {
            b.ToContainer("Products");
            b.HasPartitionKey(p => p.Category);

            // EF Core 9 breaking change: Cosmos provider now uses "$type" instead of
            // "Discriminator" by default. For existing documents that already store
            // "Discriminator", explicitly configure it to preserve backward compatibility.
            b.HasDiscriminator<string>("Discriminator");
        });
    }
}

class Product
{
    public string Id { get; set; } = null!;
    public string Name { get; set; } = null!;
    public string Category { get; set; } = null!;
}

// Example showing the fix for synchronous Cosmos DB queries.
// EF Core 9 breaking change: Synchronous I/O is no longer supported on
// the Cosmos provider. All queries must use async methods.
class CosmosQueryService
{
    // WRONG (throws in EF Core 9):
    //   var products = cosmosDb.Products.ToList();
    //
    // CORRECT — use async:
    public async Task<List<Product>> GetProductsAsync(CosmosDbContext cosmosDb)
    {
        return await cosmosDb.Products.ToListAsync();
    }
}

